-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: enrich only published short placeholders and preserve prior text; no duplicate activities.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"توثيق رحلة إلى البحرين","passage":"دوّن فريق من الطلاب خلال رحلة تعليمية أسماء المواقع التي زارها، ووصف ما شاهده بنفسه، وفصل ذلك عن معلومات نقلها مرشد تحتاج إلى مصدر موثوق. هذا المثال التعليمي أصلي من ضاديوم ولا يمثل النص الرسمي «رحلة إلى البحرين». كتابة تقرير رحلة تستلزم ترتيب الزمن والمكان والتمييز بين الملاحظة والتفسير.","prompt":"كيف فصل الفريق بين المشاهدة والمعلومات المنقولة؟","correct":"سجل الملاحظات ومصادر الأقوال","w1":"خلط جميع المعلومات","w2":"تجاهل أسماء المواقع","w3":"اعتمد على التخمين","practice":"اكتب تقرير رحلة إلى مكان تعرفه من مقدمة ووصف وملاحظات موثقة وتأمل شخصي منفصل."},{"n":2,"skill":"اسم التفضيل في المقارنة الدقيقة","passage":"في «هذا التصميمُ أدقُّ من سابقه» كلمة «أدقُّ» اسم تفضيل على وزن «أفعل» تقارن بين تصميمين في صفة الدقة. وفي صفة لا تصاغ مباشرة قد نستعين بقول «أكثر انتظامًا». ينبغي تحديد وجه المقارنة حتى لا يتحول الوصف إلى حكم عام بلا دليل.","prompt":"ما اسم التفضيل في المثال؟","correct":"أدقُّ","w1":"التصميم","w2":"من","w3":"سابقه","practice":"أنشئ خمس جمل فيها اسم تفضيل حول جودة عمل أو أداء، محددًا وجه المقارنة ومراعيًا الإعراب."},{"n":3,"skill":"كتابة تقرير وفق بيانات محددة","passage":"بيانات افتراضية للتدريب فقط: في الأسبوع الأول نُفذت أربع مهمات، وفي الثاني ست، وفي الثالث خمس. التقرير الموضوعي يذكر المدة والمصدر ويفصل الزيادة في الثاني عن الانخفاض البسيط في الثالث، ولا يجزم بأسباب التغير دون دليل.","prompt":"أي أسبوع سجّل أعلى عدد مهمات في البيانات الافتراضية؟","correct":"الأسبوع الثاني","w1":"الأسبوع الأول","w2":"الأسبوع الثالث","w3":"الأعداد متساوية","practice":"اكتب تقريرًا من فقرتين عن الأرقام مع جدول صغير ونتيجة دقيقة وفرضية موسومة بأنها تفسير محتمل."},{"n":4,"skill":"تحليل التعليق الصحفي وموقف الكاتب","passage":"نص «حديث في الحداثة» المنسوب في عنوان الدرس إلى قمر الكيلاني يتطلب قراءة أصل المقال قبل نسبة أطروحة للكاتبة. في مثال مستقل يرى متحدث أن كل تقنية جديدة تحل المشكلات، ويرد آخر بأن التقييم يحتاج أثرًا وتكلفة ومعايير سلامة. يتعلم القارئ التمييز بين التعميم والحجة المدعومة.","prompt":"ما الاعتراض الأكثر منطقية على التعميم؟","correct":"ضرورة فحص الأثر والتكلفة والسلامة","w1":"أن القديم دائمًا أفضل","w2":"أن الجديد دائمًا سيئ","w3":"إلغاء المقارنة","practice":"بعد قراءة المقال الأصلي حدد أطروحته بدليل موثق، ثم اكتب تعليقًا مؤيدًا جزئيًا أو معارضًا بحجتين."},{"n":5,"skill":"الوصف الأدبي للمكان","passage":"في نص أصلي تفتح الحديقة ممرًا للمشاة، وتنتظم الأشجار حول مساحة خضراء، ويلمع الماء وقت الصباح. يوضح الوصف علاقة العناصر بعضها ببعض ويوظف حاسة البصر دون إغراق. المثال ليس من النص المدرسي المعنون «منظر الرياض»، ولا يثبت هوية المكان الموصوف فيه.","prompt":"ما التفصيل الذي يوضح تنظيم عناصر المكان؟","correct":"انتظام الأشجار حول المساحة","w1":"اسم المدرسة","w2":"وقت الامتحان","w3":"رأي الكاتب في الرياضة","practice":"صف مكانًا في سبع جمل مع ترتيب مكاني واضح وتفصيلين حسيين، ثم احذف التكرار الزائد."},{"n":6,"skill":"النداء والتمني في التعبير","passage":"«يا طالبَ العلمِ، ثابرْ» نداء بمنادى مضاف منصوب، وفي «ليتَ الفرصةَ تتاحُ للجميع» أسلوب تمني باستخدام «ليت» واسمها منصوب. يختلف التمني عن خطة عمل أو رجاء ممكن؛ فالسياق هو الذي يوضح العاطفة والمراد.","prompt":"ما الأداة الدالة على التمني؟","correct":"ليت","w1":"يا","w2":"من","w3":"لن","practice":"اكتب ثلاث جمل نداء وثلاث جمل تمني عن التعلم، ثم اضبط المنادى واسم ليت."},{"n":7,"skill":"التعقيب الصحفي والعربية والعلم","passage":"لا يجوز تلخيص موقف أدونيس في «اللغة العربية والفكر والعلم» قبل قراءة المقال المقرر. في مثال أصلي تقترح متعلمة شرح المصطلحات العلمية بالعربية تعريفًا دقيقًا مع الإشارة إلى المقابل الأجنبي عند الحاجة. يناقش المثال وضوح التواصل ولا ينسب أي رأي إلى الشاعر أو الكاتب.","prompt":"ما المعيار الذي تقترحه المتعلمة للمصطلح العلمي؟","correct":"تعريف عربي واضح ودقيق","w1":"إلغاء التوثيق","w2":"استبعاد المتعلم","w3":"استخدام ألفاظ مبهمة","practice":"استخرج فكرة موثقة من المقال الأصلي واكتب تعقيبًا يوازن بين حجة مؤيدة وتحفظ واضح."},{"n":8,"skill":"المقالة الأدبية ووحدة الموضوع","passage":"تجمع المقالة الأدبية بين خبرة شخصية وصور فنية وبنية متماسكة. في افتتاحية أصلية يسمع المتعلم صوت المطر على نافذة صف قديم، فيتذكر قيمة الصبر والتعلم. ينبغي أن ترتبط الصور بالفكرة وأن ينتقل الكاتب منطقيًا من المقدمة إلى الفقرات فالخاتمة.","prompt":"ما الذي يمنع المقالة من التحول إلى أوصاف مفككة؟","correct":"وحدة الموضوع وترابط الفقرات","w1":"تكرار التشبيهات بلا هدف","w2":"غياب الفكرة","w3":"الإكثار من الحشو","practice":"اكتب مقالة قصيرة عن مكان يرتبط بذكرياتك، بمقدمة وعرض وخاتمة وصورتين فنيتين مدروستين."},{"n":9,"skill":"استخلاص العاطفة مع مصدر صحيح","passage":"لا يكفي عنوان «يموت الهوى مني» وحده لتحديد الشاعر أو مجريات القصيدة أو عاطفتها. في جملة أدبية مستقلة: «عاد المسافر إلى الطريق القديم، فاستيقظت في قلبه ذكرى صديق غائب». يوحي المثال بالحنين، لكنه ليس بيتًا مأخوذًا من النص المدرسي.","prompt":"ما الشعور الأقرب إلى الجملة الأصلية؟","correct":"الحنين","w1":"اللامبالاة","w2":"التهكم","w3":"الانتصار الرياضي","practice":"بعد قراءة القصيدة الموثقة استخرج مفردتين تدلان على عاطفة فعلية واشرح دلالتهما في سياق البيت."},{"n":10,"skill":"الفعل المبني للمجهول ونائب الفاعل","passage":"في «أنجزَ المهندسُ المشروعَ» يذكر الفاعل صراحة. وعند «أُنجِزَ المشروعُ» يُحذف الفاعل ويُبنى الماضي للمجهول بضم أوله وكسر ما قبل آخره، ويتحول «المشروعُ» إلى نائب فاعل مرفوع. لا يُسمّى نائب الفاعل مفعولًا به بعد التحويل.","prompt":"ما إعراب «المشروعُ» في «أُنجز المشروعُ»؟","correct":"نائب فاعل مرفوع","w1":"مفعول به منصوب","w2":"مبتدأ","w3":"مضاف إليه","practice":"حوّل خمس جمل من المبني للمعلوم إلى المجهول، واضبط الفعل ونائب الفاعل واذكر أثر الحذف في التركيز."},{"n":901,"skill":"أغراض النداء والتمني من السياق","passage":"«يا زملائي، راجعوا الخطة» نداء للتنبيه يتبعه طلب عمل، و«ليتَ كلَّ طالبٍ يجد فرصةً عادلةً للتعلم» أسلوب تمني يعبر عن رغبة. في التقييم ينبغي التمييز بين الأداة والمغزى؛ فوجود «يا» لا يكفي لفهم كامل غرض العبارة.","prompt":"ما غرض النداء في المثال الأول؟","correct":"تنبيه المخاطبين","w1":"نفي فعل","w2":"توكيد خبري","w3":"المقارنة","practice":"اكتب حوارًا من ست مداخلات توظف فيه نداءين وتمنيًا واحدًا، ثم حلل الأغراض وإعراب الأدوات."},{"n":902,"skill":"تذوق نص جبران دون اقتباس مختلق","passage":"عنوان «أغنية السعادة» المرتبط بجبران خليل جبران يتطلب مراجعة النص المدرسي ومصدره قبل اقتباس الجمل أو بيان الفلسفة الأدبية. مثال مستقل: «شعرت ليلى بالفرح عندما ساعدت جارتها على حمل الكتب». يوضح موقفًا صغيرًا قد يرتبط بالسعادة، ولا ينتسب إلى جبران.","prompt":"أين ظهر سبب فرح ليلى في المثال؟","correct":"مساعدة جارتها","w1":"ترك الكتب","w2":"غياب الجارة","w3":"إغلاق المكتبة","practice":"اقرأ النص الأصلي الموثق واستخرج عبارة تدل على تصور السعادة، ثم قارنه بموقف من إنشائك."},{"n":903,"skill":"دلالات حروف الجر بحسب استعمالها","passage":"في «ذهبتُ إلى المكتبة» تدل «إلى» على انتهاء الغاية المكانية، وفي «كتبتُ بالقلم» تفيد الباء الاستعانة بالأداة، وفي «تحدثنا عن المشروع» تفيد «عن» موضوع الحديث. تتغير معاني الحروف حسب السياق، ولذلك لا تُختزل كل أداة في معنى محفوظ واحد.","prompt":"ماذا تفيد الباء في «كتبت بالقلم»؟","correct":"الاستعانة بالأداة","w1":"انتهاء الغاية","w2":"الاستثناء","w3":"النداء","practice":"اكتب ست جمل تستخدم حروف الجر استعمالات متنوعة، ثم اشرح معنى الحرف من السياق لا من الحفظ وحده."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=12
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='e15ed6fd-370c-4980-b724-d0c19ec2c029'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='عرب 806 — اللغة العربية للتعليم الفني والمهني' AND u.semester=2 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الثاني. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_TECH_G12_T2_ARAB806_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_TECH_G12_T2_ARAB806_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_TECH_G12_T2_ARAB806_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_TECH_G12_T2_ARAB806_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;